import assert from 'node:assert/strict'
import fs from 'node:fs/promises'
import os from 'node:os'
import path from 'node:path'
import {createHash} from 'node:crypto'
import {gunzipSync} from 'node:zlib'
import test from 'node:test'
import {saveRawSourceCapture} from '../scraper-support/utils/rawCapture.js'
import {attachInventoryEvidence,readInventoryEvidence} from '../scraper-support/utils/inventoryEvidence.js'

// Complete original Immuta flat11 and its actual response values, captured
// 2026-11-11T16:41Z. Embedded for offline/CI independence; no publisher reads.
const actual=JSON.parse(gunzipSync(Buffer.from('','base64')))
const sha=bytes=>createHash('sha256').update(bytes).digest('hex')
assert.equal(actual.nativePayload.length,11)
assert.equal(actual.nativePayload[0].id,'19d612f7-5256-46e4-90ba-aa27c07a369d')
assert.equal(actual.nativePayload[0].text,'Customer Success Manager (EMEA)')
assert.equal(actual.nativePayload[0].country,'GB')
assert.equal(sha(Buffer.from(actual.response.rawBodyBase64,'base64')),'c5752933ecea44800dbcf5b774baab5b9d9b6fe75589a1c2c670a5690c6f80c5')

const temporaryDirectory=async t=>{
 const parent=path.resolve(os.tmpdir()),directory=await fs.mkdtemp(path.join(parent,'jobverify-native-capture-'))
 t.after(async()=>{assert.equal(path.dirname(path.resolve(directory)),parent);assert.ok(path.basename(directory).startsWith('jobverify-native-capture-'));await fs.rm(directory,{recursive:true,force:true})})
 return directory
}
const audit=()=>({source:'immuta',archiveNativeCollectionEvidence:true,nativePayload:structuredClone(actual.nativePayload),rawResponses:[structuredClone(actual.response)],
 sourceScopeComplete:false,lifecycleCleanupAllowed:false,applicationScreeningAcquired:false,currentProgrammeQualified:false})
const attach=(jobs,evidence)=>Object.defineProperty(jobs,'nativeCollectionEvidence',{value:evidence,configurable:true})
const options=directory=>({source:'immuta',directory,dryRun:true,now:new Date('2026-11-11T16:41:31.080Z')})
const recorded=async(jobs,directory)=>JSON.parse(await fs.readFile(await saveRawSourceCapture(jobs,options(directory)),'utf8'))

test('empty raw jobs retain the opted-in nonenumerable complete original native audit',async t=>{
 const directory=await temporaryDirectory(t),evidence=audit(),jobs=attach([],evidence)
 attachInventoryEvidence(jobs,{status:'coverage-gap',surface:'https://api.lever.co/v0/postings/immuta?mode=json',firstParty:true,listingComplete:false,pagesFetched:5,reportedTotal:11,
  indiaFacetCount:null,verifiedAt:actual.response.completedAt,reason:'archive-retention-only;not-programme-qualification',lifecycleCleanupAllowed:false})
 const beforeDescriptor=Object.getOwnPropertyDescriptor(jobs,'nativeCollectionEvidence'),beforeInventory=structuredClone(readInventoryEvidence(jobs))
 const saved=await recorded(jobs,directory)
 assert.ok(saved.nativeCollectionEvidence,'Opted-in empty native audit must survive the actual immutable capture')
 assert.deepEqual(saved.nativeCollectionEvidence,evidence)
 assert.equal(saved.nativeCollectionEvidence.nativePayload[0].descriptionPlain,actual.nativePayload[0].descriptionPlain)
 assert.deepEqual(saved.nativeCollectionEvidence.nativePayload[0].lists,actual.nativePayload[0].lists)
 assert.equal(saved.nativeCollectionEvidence.rawResponses[0].rawBodyBase64,actual.response.rawBodyBase64)
 assert.equal(saved.nativeCollectionEvidence.rawResponses[0].bodySHA256,'c5752933ecea44800dbcf5b774baab5b9d9b6fe75589a1c2c670a5690c6f80c5')
 assert.deepEqual(saved.nativeCollectionEvidence.rawResponses[0].headerEntries,actual.response.headerEntries)
 assert.deepEqual(saved.jobs,[]);assert.equal(saved.jobCount,0);assert.equal(saved.type,'capture')
 assert.deepEqual(saved.inventoryEvidence,beforeInventory);assert.equal(saved.inventoryEvidence.status,'coverage-gap')
 assert.deepEqual(Object.getOwnPropertyDescriptor(jobs,'nativeCollectionEvidence'),beforeDescriptor)
 assert.deepEqual(readInventoryEvidence(jobs),beforeInventory);assert.equal(jobs.length,0)
})

test('positive captures preserve original jobs/inventory alongside exact native audit',async t=>{
 const directory=await temporaryDirectory(t),evidence=audit(),native=actual.nativePayload[0]
 const job={title:native.text,country:native.country,sourceUrl:native.hostedUrl,jobDescription:native.descriptionPlain,sourceNativeRecord:structuredClone(native)}
 const jobs=attach([job],evidence),before=structuredClone(job)
 const saved=await recorded(jobs,directory)
 assert.ok(saved.nativeCollectionEvidence,'Positive native audit must be archived')
 assert.deepEqual(saved.jobs,[before]);assert.equal(saved.jobCount,1);assert.equal(saved.inventoryEvidence,null)
 assert.deepEqual(saved.nativeCollectionEvidence,evidence);assert.deepEqual(job,before);assert.equal(jobs.nativeCollectionEvidence,evidence)
})

test('native own nonenumerable data and JSON reserved keys are retained without prototype mutation',async t=>{
 const directory=await temporaryDirectory(t),evidence=audit()
 Object.defineProperty(evidence,'nonenumerableOriginal',{value:{literal:'retain this original field'},enumerable:false})
 evidence.reserved=JSON.parse('{"__proto__":{"marker":"original"},"constructor":"native","prototype":null}')
 const saved=await recorded(attach([],evidence),directory)
 assert.ok(saved.nativeCollectionEvidence,'Own native data must be retained')
 assert.deepEqual(saved.nativeCollectionEvidence.nonenumerableOriginal,{literal:'retain this original field'})
 assert.deepEqual(saved.nativeCollectionEvidence.reserved,JSON.parse('{"__proto__":{"marker":"original"},"constructor":"native","prototype":null}'))
 assert.equal(Object.prototype.marker,undefined);assert.equal(Object.getOwnPropertyDescriptor(evidence,'nonenumerableOriginal').enumerable,false)
})

test('shared acyclic JSON data remains complete in every native field',async t=>{
 const directory=await temporaryDirectory(t),shared={conditions:['3-5+ years','Join by 2026-12-01'],unset:null},evidence=audit()
 evidence.first=shared;evidence.second=shared
 const saved=await recorded(attach([],evidence),directory)
 assert.ok(saved.nativeCollectionEvidence,'Shared native data must be retained')
 assert.deepEqual(saved.nativeCollectionEvidence.first,shared);assert.deepEqual(saved.nativeCollectionEvidence.second,shared)
})

test('unflagged inherited and accessor audit metadata keep prior capture behavior without calls',async t=>{
 const directory=await temporaryDirectory(t);let calls=0
 const noFlag={source:'immuta',get dangerous(){calls++;throw Error('do not read')},toJSON(){calls++;throw Error('do not serialize')}}
 const inheritedFlag=Object.assign(Object.create({archiveNativeCollectionEvidence:true}),{source:'immuta'})
 const accessorFlag={source:'immuta'};Object.defineProperty(accessorFlag,'archiveNativeCollectionEvidence',{get(){calls++;return true}})
 const outerGetter=[];Object.defineProperty(outerGetter,'nativeCollectionEvidence',{get(){calls++;throw Error('do not invoke outer')}})
 const inheritedAudit=[];Object.setPrototypeOf(inheritedAudit,Object.assign(Object.create(Array.prototype),{nativeCollectionEvidence:audit()}))
 for(const jobs of [attach([],noFlag),attach([],{...audit(),archiveNativeCollectionEvidence:false}),attach([],inheritedFlag),attach([],accessorFlag),outerGetter,inheritedAudit]){
  const saved=await recorded(jobs,directory);assert.equal(Object.hasOwn(saved,'nativeCollectionEvidence'),false);assert.deepEqual(saved.jobs,[])
 }
 assert.equal(calls,0)
})

test('a proxy audit carrier cannot establish a descriptor-backed opt-in and runs no traps',async t=>{
 const directory=await temporaryDirectory(t);let calls=0
 const proxy=new Proxy(audit(),{get(){calls++;throw Error('proxy get')},getOwnPropertyDescriptor(){calls++;throw Error('proxy descriptor')},getPrototypeOf(){calls++;throw Error('proxy prototype')},ownKeys(){calls++;throw Error('proxy keys')}})
 const saved=await recorded(attach([],proxy),directory)
 assert.equal(Object.hasOwn(saved,'nativeCollectionEvidence'),false);assert.deepEqual(saved.jobs,[]);assert.equal(calls,0)
})

test('live and missing-directory calls do not validate or serialize opted-in native data',async t=>{
 const directory=await temporaryDirectory(t),evidence=audit();evidence.unsupported=1n
 const jobs=attach([],evidence),previous=process.env.SCRAPER_RAW_CAPTURE_DIRECTORY
 delete process.env.SCRAPER_RAW_CAPTURE_DIRECTORY
 t.after(()=>{if(previous===undefined)delete process.env.SCRAPER_RAW_CAPTURE_DIRECTORY;else process.env.SCRAPER_RAW_CAPTURE_DIRECTORY=previous})
 assert.equal(await saveRawSourceCapture(jobs,{source:'immuta',directory,dryRun:false}),null)
 assert.equal(await saveRawSourceCapture(jobs,{source:'immuta',directory:' ',dryRun:true}),null)
 assert.equal(await saveRawSourceCapture(jobs,{source:'immuta',dryRun:true}),null)
 assert.deepEqual(await fs.readdir(directory),[])
})

for(const [label,mutate] of [
 ['mismatching source',value=>{value.source='loadsmart'}],
 ['missing source',value=>{delete value.source}],
 ['nonstring source',value=>{value.source={name:'immuta'}}],
 ['undefined property',value=>{value.condition=undefined}],
 ['nonfinite number',value=>{value.condition=NaN}],
 ['infinite number',value=>{value.condition=Infinity}],
 ['negative zero',value=>{value.condition=-0}],
 ['BigInt',value=>{value.condition=1n}],
 ['function',value=>{value.condition=()=>null}],
 ['symbol value',value=>{value.condition=Symbol('condition')}],
 ['symbol key',value=>{value[Symbol('condition')]='original'}],
 ['Date',value=>{value.condition=new Date('2026-11-11T16:41:31.080Z')}],
 ['Map',value=>{value.condition=new Map([['country','GB']])}],
 ['Set',value=>{value.condition=new Set(['GB'])}],
 ['typed array',value=>{value.condition=new Uint8Array([1,2,3])}],
 ['sparse array',value=>{value.condition=new Array(2)}],
 ['array custom property',value=>{value.condition=[];value.condition.authored='original'}],
 ['object cycle',value=>{value.condition=value}],
 ['array cycle',value=>{value.condition=[];value.condition.push(value.condition)}],
 ['custom prototype',value=>{value.condition=Object.assign(Object.create({unpublished:'inherited'}),{original:'keep'})}],
])test('flagged native '+label+' rejects before any archive filesystem write',async t=>{
 const directory=await temporaryDirectory(t),evidence=audit();mutate(evidence)
 await assert.rejects(saveRawSourceCapture(attach([],evidence),options(directory)),/nativeCollectionEvidence/i)
 assert.deepEqual(await fs.readdir(directory),[])
})

for(const kind of ['source getter','nested getter','array getter','toJSON function','toJSON getter','nested proxy'])test('flagged native '+kind+' rejects without executing user code',async t=>{
 const directory=await temporaryDirectory(t),evidence=audit();let calls=0
 const execute=()=>{calls++;throw Error('must not execute')}
 if(kind==='source getter')Object.defineProperty(evidence,'source',{get:execute})
 else if(kind==='nested getter'){evidence.condition={};Object.defineProperty(evidence.condition,'original',{get:execute})}
 else if(kind==='array getter'){evidence.condition=[1];Object.defineProperty(evidence.condition,'0',{get:execute})}
 else if(kind==='toJSON function')evidence.toJSON=execute
 else if(kind==='toJSON getter')Object.defineProperty(evidence,'toJSON',{get:execute})
 else evidence.condition=new Proxy({original:'data'},{get:execute,getPrototypeOf:execute,getOwnPropertyDescriptor:execute,ownKeys:execute})
 await assert.rejects(saveRawSourceCapture(attach([],evidence),options(directory)),/nativeCollectionEvidence/i)
 assert.equal(calls,0);assert.deepEqual(await fs.readdir(directory),[])
})
